TEST(OperationSpecificStatefulValidation,Performance_AllFamiliesAvoidFullStoreScan){class Counting:public ObjectStore{public:const ObjectStore&d;mutable int all=0;explicit Counting(const ObjectStore&x):d(x){}std::size_t size()const noexcept override{return d.size();}bool contains(const ObjectId&i)const noexcept override{return d.contains(i);}const ObjectRecord*find(const ObjectId&i)const noexcept override{return d.find(i);}std::vector<ObjectRecord>allObjects()const override{++all;return d.allObjects();}std::vector<ObjectRecord>children(const std::optional<ObjectId>&p)const override{return d.children(p);}};ReferenceObjectStore base;seed<ReplaceObjectsStatePlanInputs>(base,{shape(1)});Counting c(base);ReplaceObjectsStatePlanInputs o;EXPECT_TRUE(validateSetTransformsState({{{id(1),{}}}},c,&o).ok());EXPECT_EQ(c.all,0);EXPECT_TRUE(validateSetObjectSizeState({{{id(1),2,3}}},c,&o).ok());EXPECT_EQ(c.all,0);}
